// Detect Direction — deterministic, API-less.
// Turkish uses characters English never does. We count how many appear in the
// page's anonymized text; any meaningful presence => the source is Turkish.
// Emits `direction` as a field BOTH the translator and the glossary read.
// This is real detection, not a stub — the demo is genuinely bidirectional.

const text = $json.anonymized_text || "";

// Characters that occur in Turkish but not in standard English orthography.
const turkishChars = (text.match(/[ışğçöüİı]/g) || []).length;

// A tiny threshold guards against a stray character (e.g. a name, a stray
// diacritic in an English doc). A genuinely Turkish page clears this easily;
// an English page sits at ~0.
const isTurkish = turkishChars >= 3;

return {
  json: {
    ...$json,                       // carry the whole item through untouched
    direction: isTurkish ? "tr>en" : "en>tr",
    direction_debug: {             // visible in the run, aids demo narration
      turkish_char_count: turkishChars,
      decided: isTurkish ? "tr>en" : "en>tr",
    },
  },
};

// Wrap to JSON — structure the translation output for downstream stages.
// The model (or stub) returned PLAIN TEXT; this node builds the structured
// item around it. n8n owns the structuring, not the LLM — that's what keeps
// placeholders safe (the model never had to emit JSON).
//
// Run mode: Run Once for Each Item (per-page, keeps page_index aligned).

// ⬇️ THE ONE FIELD TO ADJUST after you see the real Gemini output.
// Common candidates by n8n/Gemini node version: $json.text, $json.content,
// $json.response, $json.message.content. Run the node once, look at where the
// translated string actually lands, and set this to match.
const translatedText = $json.content.parts[0].text || "";

return {
  json: {
    page_index: $('Set Translation Direction').item.json.page_index,        // keeps this page pairable downstream
    direction: $('Set Translation Direction').item.json.direction,          // read by the eventual glossary + restore
    translated_text: translatedText,     // the (still-tokenized) translation
    restore_map: $('Set Translation Direction').item.json.restore_map,      // LOCAL — rides to restore, never to cloud
  },
};

// Gate decision helper (read-all version) — runs per candidate item.
// Instead of relying on a per-term Sheets lookup (which drops non-matches),
// we match against ALL glossary rows read upstream, so WE control the no-match
// case and route it to append instead of letting the item vanish.

const candidate = $('Parse and Dedupe').item.json;   // the candidate flows straight through now

// Pull every existing glossary row from the read-all node.
const allRows = $('Read Glossary').all().map(i => i.json);   // ← your read-all node's name

// Find a row matching this candidate on (source_term, direction).
const match = allRows.find(r =>
  r.source_term === candidate.source_term &&
  r.direction === candidate.direction
);

let route;
if (!match) {
  route = "append";
} else if (String(match.verified).toUpperCase() === "TRUE") {
  route = "skip";
} else {
  route = "update";
}

return {
  json: {
    ...candidate,
    _route: route,
    _matched_row: match || null,
  },
};

// Parse + Dedupe — Run Once for All Items.
// Consumes all 5 pages' raw Gemini extractor outputs. For each: strip code
// fences, JSON.parse the array. Flatten all pages into one term list. Then
// dedupe by (source_term, direction): collapse agreeing duplicates, and for
// conflicting translations, keep the highest-confidence as target_term while
// recording ALL competing translations in review_note for the human.

const items = $input.all();
const sourceDoc = "SYNTHETIC_Divorce_Decree";

// --- 1. Parse every page's array, flatten into one list of raw pairs ---
const allPairs = [];
for (const item of items) {
  const raw = item.json?.content?.parts?.[0]?.text || "[]";
  // Strip ```json ... ``` or ``` ... ``` fences if Gemini wrapped the output.
  const cleaned = raw.replace(/```json\s*/gi, "").replace(/```/g, "").trim();

  let parsed;
  try {
    parsed = JSON.parse(cleaned);
    if (!Array.isArray(parsed)) parsed = [];
  } catch (e) {
    parsed = [];   // malformed page -> contribute nothing, don't crash the run
  }

  // Direction: read from the item if the extractor carried it, else default.
  // (The extractor's response item may not carry direction; fall back to en>tr
  //  for this English-source demo. Adjust if you thread direction through.)
  const direction = item.json?.direction || "en>tr";

  for (const p of parsed) {
    if (!p || !p.source_term || !p.target_term) continue;   // skip junk
    allPairs.push({
      source_term: String(p.source_term).trim(),
      target_term: String(p.target_term).trim(),
      direction,
      confidence: typeof p.confidence === "number" ? p.confidence : null,
    });
  }
}

// --- 2. Group by (source_term, direction) ---
// Key is case-sensitive on source_term intentionally: "Order" vs "order" could
// be different usages; the human can merge if needed. Direction is part of key
// because a term is a distinct entry per translation direction.
const groups = new Map();
for (const pair of allPairs) {
  const key = `${pair.source_term.toLowerCase()}||${pair.direction}`;
  if (!groups.has(key)) groups.set(key, []);
  groups.get(key).push(pair);
}

// --- 3. Collapse each group to ONE row, flag conflicts ---
const deduped = [];
for (const [key, pairs] of groups) {

  // Highest-confidence pair (kept — drives confidence + fallback display).
  const best = pairs.reduce((a, b) =>
    ((b.confidence ?? -1) > (a.confidence ?? -1) ? b : a)
  );

  // Non-all-caps display form for source_term (kept — heading vs body casing).
  const displayForm = pairs.find(p => p.source_term !== p.source_term.toUpperCase())
    || best;

  // --- Collapse target translations that differ ONLY by case ---
  // "Davacı" and "davacı" are the same translation, capitalized differently by
  // sentence position. Group targets by Turkish-lowercased form; only genuinely
  // different translations (different letters, not just case) remain distinct.
  const targetGroups = new Map();
  for (const p of pairs) {
    const norm = p.target_term.toLocaleLowerCase("tr");
    if (!targetGroups.has(norm)) {
      targetGroups.set(norm, p.target_term);   // keep first-seen casing for display
    }
  }
  const distinctTargets = [...targetGroups.values()];

  // Choose display target: prefer a capitalized form over all-lowercase.
  let chosenTarget = best.target_term;
  const capitalizedVariant = distinctTargets.find(
    t => t[0] === t[0].toLocaleUpperCase("tr") && t[0] !== t[0].toLocaleLowerCase("tr")
  );
  if (capitalizedVariant &&
      best.target_term === best.target_term.toLocaleLowerCase("tr")) {
    chosenTarget = capitalizedVariant;
  }

  let reviewNote = "";
  if (distinctTargets.length > 1) {
    reviewNote = "CONFLICT — competing translations: " +
      distinctTargets.map(t => `"${t}"`).join(" | ");
  }

  deduped.push({
    json: {
      source_term: displayForm.source_term,
      target_term: chosenTarget,          // ← case-collapsed pick (was best.target_term)
      direction: best.direction,
      confidence: best.confidence,
      verified: "FALSE",
      source_doc: sourceDoc,
      review_note: reviewNote,
    },
  });
}

return deduped;

// Build Structured Text — reconstruct paragraph boundaries from OCR hierarchy.
//
// WHY THIS EXISTS
// ---------------
// /ocr's `text` field joins EVERY line with "\n" — so a mid-sentence wrap and a
// real paragraph break look identical downstream. The structure isn't lost, it's
// just not serialized: each line carries a line_id of "block:par:line", and
// Tesseract already knows which lines share a paragraph. This node reads that
// hierarchy back out and emits `structured_text`, where intra-paragraph wraps
// collapse to spaces and real block/paragraph boundaries become blank lines.
//
// WHAT IT DOES NOT DO
// -------------------
// It never mutates `text` or `anonymized_text`. `text` is the coordinate system
// that /detect-pii spans and /ocr char_spans both index into — changing it would
// break /redact's char_span -> pixel mapping. This node is purely ADDITIVE.
//
// THE INDEX-ZIP GUARANTEE
// -----------------------
// We pair anonymized_text.split("\n")[i] with lines[i]. That's valid because in
// ocr_extract.extract(), `full_text` and `lines` are built from the SAME `order`
// array in the same sequence, and words never contain "\n". Anonymization
// preserves that pairing — UNLESS a PII span crosses a line break and its
// placeholder swallows the "\n". Then every later line pairs with the wrong
// line_id and we'd emit plausible-looking, silently-wrong paragraphs. Hence the
// count guard below: verify the precondition, don't guess. Same instinct as
// /redact's raster-parity tripwire.

const anonText = $json.anonymized_text || "";
const pageIndex = $json.page_index;

// --- Recover `lines` from /ocr -------------------------------------------
// The /anonymize HTTP node replaced the item, so `lines` is gone from $json.
// Match on page_index rather than using $('Merge').item: that would rely on
// pairedItem metadata surviving an HTTP node's item replacement. Matching by a
// real document-structural fact is order-independent and provably correct —
// the same reasoning behind the Merge node's By Matching Fields config.
const mergedItem = $('Merge').all().find(
  (i) => i.json.page_index === pageIndex
);
const ocrLines = mergedItem?.json?.lines ?? null;

// --- Soft-fail helper -----------------------------------------------------
// A structure failure must NEVER take down a run. On any precondition miss we
// pass anonymized_text through verbatim: the page translates exactly as it does
// today, flagged so the failure is visible rather than silent.
function softFail(reason, anonCount, ocrCount) {
  return {
    json: {
      ...$json,
      structured_text: anonText,
      structure_debug: {
        ocr_line_count: ocrCount,
        anon_line_count: anonCount,
        paragraph_count: null,
        structure_recovered: false,
        reason,
      },
    },
  };
}

const anonLines = anonText.split("\n");

// --- Preconditions --------------------------------------------------------
if (!anonText) {
  return softFail("empty anonymized_text", anonLines.length, ocrLines?.length ?? null);
}
if (!mergedItem) {
  return softFail(`no Merge item matching page_index ${pageIndex}`, anonLines.length, null);
}
if (!Array.isArray(ocrLines) || ocrLines.length === 0) {
  return softFail("missing or empty lines[] from /ocr", anonLines.length, ocrLines?.length ?? null);
}
// THE guard. A mismatch means the index-zip assumption is broken — most likely a
// placeholder swallowed a newline (a known anonymizer boundary case, logged for
// anonymize_core_v2). This detects it; it does not fix it.
if (anonLines.length !== ocrLines.length) {
  return softFail(
    "line count mismatch (anonymization may have swallowed a newline)",
    anonLines.length,
    ocrLines.length
  );
}

// --- Reconstruct paragraphs ----------------------------------------------
// line_id is the full "block:par:line" triple. Drop the line component: lines
// sharing a block:par prefix are the same paragraph, wrapped. A change of prefix
// is a real boundary.
const paragraphs = [];
let current = [];
let prevPrefix = null;

for (let i = 0; i < anonLines.length; i++) {
  const lineId = ocrLines[i]?.line_id;
  if (typeof lineId !== "string") {
    return softFail(`malformed line_id at index ${i}`, anonLines.length, ocrLines.length);
  }
  const prefix = lineId.split(":").slice(0, 2).join(":");   // "block:par"

  if (prevPrefix !== null && prefix !== prevPrefix) {
    paragraphs.push(current.join(" "));   // close the open paragraph
    current = [];
  }
  current.push(anonLines[i]);
  prevPrefix = prefix;
}
if (current.length) {
  paragraphs.push(current.join(" "));     // flush the final paragraph
}

// Wraps collapse to spaces within a paragraph; paragraphs separate with a blank
// line. This is the shape the translator prompt (Stage 2) will consume.
const structuredText = paragraphs.join("\n\n");

return {
  json: {
    ...$json,                     // carry the item through untouched
    structured_text: structuredText,
    structure_debug: {
      ocr_line_count: ocrLines.length,
      anon_line_count: anonLines.length,
      paragraph_count: paragraphs.length,
      structure_recovered: true,
      reason: null,
    },
  },
};

// Aggregate Pages — Run Once for All Items.
// Collect all restored pages into one ordered item for document assembly.
// Sort by page_index (never trust arrival order — fan-in can reorder).

const pages = $input.all()
  .map(i => i.json)
  .sort((a, b) => a.page_index - b.page_index);

// Recover direction per page (dropped by /restore's response shape) and derive
// one document-level direction. All pages of a single source document should
// agree; if they don't, that's a real signal something misfired upstream
// (e.g. the Turkish-char-count heuristic tripped on one page) -- flag it
// rather than silently picking one and hiding the disagreement.
const directions = pages.map(p => {
  const match = $('Set Translation Direction').all()
    .find(i => i.json.page_index === p.page_index);
  return match?.json?.direction ?? null;
});
const uniqueDirections = [...new Set(directions.filter(Boolean))];
const direction = uniqueDirections[0] ?? null;
const direction_consistent = uniqueDirections.length <= 1;

// Surface integrity flags across the whole document, so assembly (and the
// reviewer) sees in one place whether any page had a dropped or stray token.
const pagesWithFlags = pages.filter(
  p => (p.missing_placeholders?.length || p.unresolved_tokens?.length)
);

return [{
  json: {
    page_count: pages.length,
    pages: pages.map(p => ({
      page_index: p.page_index,
      restored_text: p.restored_text,
      missing_placeholders: p.missing_placeholders ?? [],
      unresolved_tokens: p.unresolved_tokens ?? [],
    })),
    has_integrity_flags: pagesWithFlags.length > 0,
    flagged_pages: pagesWithFlags.map(p => p.page_index),
    direction: direction,
    direction_consistent: direction_consistent
  },
}];
